CREATE UNIQUE INDEX sdo_one_per_work ON sdo_cases(tenant_id,object_work_id);
ALTER TABLE risk_settings ADD CHECK(red_variance<yellow_variance AND escalate_director_days>escalate_technical_days);
ALTER TABLE users ADD CHECK(role IN ('GENERAL_DIRECTOR','TECHNICAL_DIRECTOR','PROJECT_MANAGER','CONSTRUCTION_CONTROL','PTO','SDO','DEPARTMENT_HEAD','ADMIN','CONTRACTOR_VIEWER'));
ALTER TABLE inspections ADD CHECK(status IN ('NOT_SUBMITTED','WAITING','IN_REVIEW','ISSUES_FOUND','REINSPECTION','ACCEPTED','REJECTED','BLOCKED'));
ALTER TABLE issues ADD CHECK(status IN ('OPEN','IN_PROGRESS','READY_FOR_VERIFICATION','CLOSED','REJECTED'));
ALTER TABLE executive_packages ADD CHECK(status IN ('DRAFT','IN_PROGRESS','READY','TRANSFERRED_TO_SDO','RETURNED'));
ALTER TABLE executive_documents ADD CHECK(status IN ('NOT_STARTED','DRAFT','IN_PROGRESS','WAITING_DOCUMENT','WAITING_CERTIFICATE','WAITING_APPROVAL','READY','APPROVED'));
ALTER TABLE sdo_cases ADD CHECK(status IN ('NOT_TRANSFERRED','READY_FOR_TRANSFER','TRANSFERRED','IN_PROGRESS','NEEDS_CLARIFICATION','CALCULATED','READY_TO_CLOSE','CLOSED'));
ALTER TABLE sdo_cases ADD CHECK(calculated_value>=0 AND accepted_closing_value>=0);
ALTER TABLE financial_closings ADD CHECK(period ~ '^\d{4}-(0[1-9]|1[0-2])$');
ALTER TABLE executive_documents ADD CHECK(type IN ('AOSR','EXECUTIVE_SCHEME','CERTIFICATE','PASSPORT','LAB_REPORT','OTHER'));
